package com.historic.app.data

private fun e(
    id: String, war: War, year: Int, month: Int, date: String, title: String, place: String,
    lat: Double, lon: Double, summary: String, detail: String,
) = HistoricEvent(id, war, year, month, date, title, place, lat, lon, summary, detail)

private fun m(
    id: String, war: War, year: Int, month: Int, date: String, title: String, place: String,
    lat: Double, lon: Double, phase: String, summary: String, detail: String,
) = HistoricEvent(id, war, year, month, date, title, place, lat, lon, summary, detail, malay = true, phase = phase)

